const text = $json.text;
const maxLength = 4000;

const paragraphs = text.split('\n');
let current = '';
const result = [];

for (const p of paragraphs) {
  if ((current + p).length > maxLength) {
    result.push({ json: { chunk: current } });
    current = '';
  }
  current += p + '\n';
}

if (current) {
  result.push({ json: { chunk: current } });
}

return result;
